"""Top-down videos: real defenders vs ghost (all 10 generated by the phase-2 model) on test scenes. CPU only.
   python make_video.py
"""
import argparse, os
import numpy as np
import torch
import matplotlib; matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import Rectangle, Circle, Arc
from matplotlib.collections import LineCollection
from matplotlib.lines import Line2D
import imageio_ffmpeg
from src import load, scenes as S, roles, model as M, evaluate as E

ap = argparse.ArgumentParser()
ap.add_argument('--model', default='outputs/wc_events_phase2/model_phase2.pt')
ap.add_argument('--games', default='10513,3816,3817', help='test games of the 23-game split')
ap.add_argument('--per-game', type=int, default=1)
ap.add_argument('--min-s', type=float, default=8)
ap.add_argument('--max-s', type=float, default=25)
ap.add_argument('--fps', type=int, default=30)
ap.add_argument('--raw', default=load.RAW)
ap.add_argument('--out', default='outputs/videos')
ap.add_argument('--name', default='ghost_phase2_all', help='file name of the combined video')
a = ap.parse_args()
torch.set_num_threads(2)
os.makedirs(a.out, exist_ok=True)

ck = torch.load(a.model, map_location='cpu', weights_only=False)
TD, TA = np.asarray(ck['template_def']), np.asarray(ck['template_att'])
net = M.RoleLSTMs(hidden=ck['state']['wh.0'].shape[1])
net.load_state_dict(ck['state']); net.eval()
tmpl = torch.tensor(TD)

GRASS, GRASS2, LINE = '#3f8a4a', '#468f51', 'white'
BLUE, RED, ATT, BALL = '#1f5fbf', '#e0433a', '#f4f4f4', '#ffb000'


def pitch(ax):
    ax.add_patch(Rectangle((-57, -38), 114, 76, color=GRASS, zorder=0))
    for k in range(10):
        if k % 2:
            ax.add_patch(Rectangle((-52.5 + k * 10.5, -34), 10.5, 68, color=GRASS2, zorder=0))
    kw = dict(fill=False, ec=LINE, lw=1.6, zorder=1)
    ax.add_patch(Rectangle((-52.5, -34), 105, 68, **kw))
    ax.plot([0, 0], [-34, 34], c=LINE, lw=1.6, zorder=1)
    ax.add_patch(Circle((0, 0), 9.15, **kw))
    for sx in (-1, 1):
        x0 = sx * 52.5
        ax.add_patch(Rectangle((x0 - (16.5 if sx > 0 else 0), -20.16), 16.5, 40.32, **kw))
        ax.add_patch(Rectangle((x0 - (5.5 if sx > 0 else 0), -9.16), 5.5, 18.32, **kw))
        ax.add_patch(Arc((x0 - sx * 11, 0), 18.3, 18.3, theta1=(127 if sx > 0 else -53), theta2=(233 if sx > 0 else 53),
                         ec=LINE, lw=1.6, zorder=1))
        ax.plot([x0, x0 + sx * 1.5], [-3.66, -3.66], c=LINE, lw=1.6); ax.plot([x0, x0 + sx * 1.5], [3.66, 3.66], c=LINE, lw=1.6)
        ax.plot([x0 + sx * 1.5] * 2, [-3.66, 3.66], c=LINE, lw=1.6)
    ax.set_xlim(-57, 57); ax.set_ylim(-38, 38); ax.set_aspect('equal'); ax.axis('off')


def lerp(arr, f):
    i = int(np.floor(f)); j = min(i + 1, len(arr) - 1); w = f - i
    return arr[i] * (1 - w) + arr[j] * w


def frames(s, gh, title, fps):
    """Yields RGB frames (1280x720) for one scene."""
    up = fps // 10
    L = s['L']
    fig = plt.figure(figsize=(12.8, 7.2), dpi=100)
    fig.patch.set_facecolor('#1d1d1b')
    ax = fig.add_axes([0.03, 0.08, 0.94, 0.80])
    pitch(ax)
    trail = LineCollection([], colors=RED, linewidths=2, alpha=0.45, zorder=3)
    links = LineCollection([], colors='#ffd2cf', linewidths=1.2, linestyles='--', alpha=0.9, zorder=3)
    ax.add_collection(trail); ax.add_collection(links)
    att = ax.scatter([], [], s=150, c=ATT, edgecolors='#333', linewidths=1, zorder=4)
    agk = ax.scatter([], [], s=150, c='#bdbdbd', edgecolors='#333', marker='s', zorder=4)
    dgk = ax.scatter([], [], s=150, c='#0d2f66', edgecolors='white', marker='s', zorder=4)
    ghost = ax.scatter([], [], s=190, facecolors=(0.88, 0.26, 0.23, 0.6), edgecolors=RED, linewidths=1.5, zorder=5)
    real = ax.scatter([], [], s=190, linewidths=1.8, zorder=6)
    ball = ax.scatter([], [], s=70, c=BALL, edgecolors='black', linewidths=1, zorder=7)
    labels = [ax.text(0, 0, str(r + 1), color='white', fontsize=7.5, weight='bold', ha='center', va='center', zorder=8)
              for r in range(10)]
    fig.text(0.03, 0.955, title, color='white', fontsize=13, weight='bold', va='center')
    info = fig.text(0.03, 0.905, '', color='#dddddd', fontsize=11.5, va='center')
    fig.legend(handles=[Line2D([], [], marker='o', ls='', mfc=BLUE, mec='white', ms=11, label='real defender (seen on camera)'),
                        Line2D([], [], marker='o', ls='', mfc='none', mec=BLUE, mew=2, ms=11, label='real defender (off camera, estimated)'),
                        Line2D([], [], marker='o', ls='', mfc=(0.88, 0.26, 0.23, 0.6), mec=RED, ms=11, label='ghost (model, all 10 generated)'),
                        Line2D([], [], marker='o', ls='', mfc=ATT, mec='#333', ms=11, label='attacker'),
                        Line2D([], [], marker='o', ls='', mfc=BALL, mec='black', ms=8, label='ball')],
               loc='lower center', ncol=5, frameon=False, fontsize=9.5, labelcolor='white', bbox_to_anchor=(0.5, 0.0))
    n = (L - 1) * up + 1
    hold = [0] * fps + list(range(n)) + [n - 1] * int(1.5 * fps)
    for k in hold:
        f = k / up
        D, G, A = lerp(s['D'], f), lerp(gh, f), lerp(s['A'], f)
        vis = s['vis'][int(round(f))]
        real.set_offsets(D)
        real.set_facecolors([BLUE if v else 'none' for v in vis]); real.set_edgecolors(['white' if v else BLUE for v in vis])
        ghost.set_offsets(G); att.set_offsets(A)
        agk.set_offsets([lerp(s['Agk'], f)]); dgk.set_offsets([lerp(s['Dgk'], f)]); ball.set_offsets([lerp(s['ball'], f)])
        links.set_segments([[D[r], G[r]] for r in range(10)])
        lo = max(0.0, f - 1.0)
        ts = np.linspace(lo, f, 8)
        trail.set_segments([[lerp(gh, t)[r] for t in ts] for r in range(10)])
        for r in range(10):
            labels[r].set_position(D[r])
        d = np.linalg.norm(D - G, axis=1)
        dv = d[vis].mean() if vis.any() else float('nan')
        info.set_text(f'{f / 10:4.1f} s / {(L - 1) / 10:.1f} s    ghost vs real, mean distance (seen players): {dv:4.1f} m'
                      f'    within 3 m: {int((d[vis] < 3).sum())}/{int(vis.sum())}')
        fig.canvas.draw()
        yield np.ascontiguousarray(np.asarray(fig.canvas.buffer_rgba())[..., :3])
    plt.close(fig)


def writer(path, fps):
    w = imageio_ffmpeg.write_frames(path, (1280, 720), fps=fps, codec='libx264', pix_fmt_out='yuv420p',
                                    quality=7, macro_block_size=8)
    w.send(None)
    return w


allw = writer(f'{a.out}/{a.name}.mp4', a.fps)
total_s = 0.0
for g in a.games.split(','):
    trk = load.load_game(g, a.raw, cache=f'outputs/cache/{g}_10fps.npz')
    sc = S.cut_scenes(trk, load.load_meta(g, a.raw)[2])[0]
    roles.apply_roles(sc, TD, TA)
    names = trk['info']['names']
    cand = [i for i, s in enumerate(sc) if a.min_s * 10 <= sc[i]['L'] - 1 <= a.max_s * 10]
    chosen = sorted(cand, key=lambda i: -sc[i]['vis'].mean())[:a.per_game]
    for i in sorted(chosen, key=lambda i: sc[i]['start_frame']):        # in match order
        s = sc[i]
        total_s += (s['L'] - 1) / 10 + 2.5
        gh = E.ghost(net, sc, i, tmpl, 'cpu', joint=True)
        mm, ss = divmod(int(s['time']), 60)
        title = (f'{names["home"]} vs {names["away"]}  |  {s["defend_name"]} defending (own goal on the left)  |  '
                 f'half {s["period"]} {mm:02d}:{ss:02d}  |  ends: {s["why"].replace("_", " ")}')
        p = f'{a.out}/ghost_{g}_{s["start_frame"]}.mp4'
        w = writer(p, a.fps)
        for fr in frames(s, gh, title, a.fps):
            b = fr.tobytes(); w.send(b); allw.send(b)
        w.close()
        err = np.linalg.norm(gh[-1] - s['D'][-1], axis=-1)
        print(f'{p}: {(s["L"] - 1) / 10:.1f} s, VISIBLE {s["vis"].mean():.0%}, ghost error at end {err.mean():.1f} m', flush=True)
allw.close()
print('combined:', f'{a.out}/{a.name}.mp4', f'{total_s / 60:.1f} min')
